bounded_host_request.command:
set -euo pipefail
name=gace-createvdobot-videobot-poll-1
src=ec00440306f6d802310f48ff2dc4953beae61848
target="$HOME/.local/share/gace-create-videobot/sticker-poll-$src"
test -f "$target/deploy/compose.videobot.poll.yaml" || { echo VIDEO_STAGE_MISSING; exit 61; }
docker run --rm --network none --pull never --entrypoint /bin/sh create-videobot:local-poll -c 'grep -q "Myビデオを見る" /opt/videobot/src/telegram/creatorUi.mjs' || { echo VIDEO_IMAGE_OLD; exit 62; }
token="$(docker inspect -f '{{range .Mounts}}{{if eq .Destination "/run/secrets/videobot_telegram_token"}}{{.Source}}{{end}}{{end}}' "$name")"
dbpass="$(docker inspect -f '{{range .Mounts}}{{if eq .Destination "/run/secrets/videobot_db_password"}}{{.Source}}{{end}}{{end}}' "$name")"
pin="$(docker inspect -f '{{range .Mounts}}{{if eq .Destination "/var/lib/videobot/sticker-entry"}}{{.Source}}{{end}}{{end}}' "$name")"
test -f "$token" && test -f "$dbpass" && test -d "$pin" || { echo VIDEO_EXISTING_MOUNT_NOT_FOUND; exit 63; }
pg="$(docker ps --format '{{.Names}}' | grep -Ei '(^|[-_])postgres([-_]|$)' || true)"
test "$(printf '%s\n' "$pg" | sed '/^$/d' | wc -l)" -eq 1 || exit 64
user="$(docker exec "$pg" sh -c 'printf %s "$POSTGRES_USER"')"
net="$(docker inspect -f '{{range $k,$v := .NetworkSettings.Networks}}{{println $k}}{{end}}' "$pg" | sed '/^$/d')"
test -n "$user" && test "$net" = deploy_default || exit 65
export VIDEOBOT_TELEGRAM_TOKEN_SOURCE="$token" VIDEOBOT_DB_PASSWORD_SOURCE="$dbpass" VIDEOBOT_STICKER_PIN_STATE_SOURCE="$pin" GSERVER_POSTGRES_USER="$user" GSERVER_POSTGRES_NETWORK="$net"
docker compose -p gace-createvdobot -f "$target/deploy/compose.videobot.poll.yaml" config --quiet || { echo VIDEO_COMPOSE_CONFIG_BAD; exit 66; }
docker compose -p gace-createvdobot -f "$target/deploy/compose.videobot.poll.yaml" up -d --no-build --force-recreate videobot-poll >/dev/null 2>&1 || { echo VIDEO_COMPOSE_RESTART_FAILED; exit 67; }
sleep 10
test "$(docker inspect -f '{{.State.Running}}' "$name")" = true || { echo VIDEO_POLLER_NOT_RUNNING; exit 68; }
docker logs --tail 100 "$name" 2>&1 | grep -q '^CREATOR_DM_POLL_READY=PASS$' || { echo VIDEO_POLLER_READY_MISSING; exit 69; }
docker exec "$name" sh -c 'grep -q "Myビデオを見る" /opt/videobot/src/telegram/creatorUi.mjs && grep -q "replyToMessageId" /opt/videobot/src/telegram/creatorScreenTransport.mjs && command -v ffmpeg >/dev/null' || { echo VIDEO_RUNNING_CODE_MISMATCH; exit 70; }
echo VIDEO_MYVIDEOS_PREVIEW_LIVE_CODE=PASS
